import{_ as t,o as n,c as e,a5 as a}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Định nghĩa file task.md","description":"","frontmatter":{},"headers":[],"relativePath":"feature/system-maintenance/definition/task.md","filePath":"feature/system-maintenance/definition/task.md"}'),c={name:"feature/system-maintenance/definition/task.md"};function h(o,i,l,d,r,g){return n(),e("div",null,[...i[0]||(i[0]=[a('<h1 id="đinh-nghia-file-task-md" tabindex="-1">Định nghĩa file <code>task.md</code> <a class="header-anchor" href="#đinh-nghia-file-task-md" aria-label="Permalink to &quot;Định nghĩa file `task.md`&quot;">​</a></h1><h2 id="muc-đich" tabindex="-1">Mục đích <a class="header-anchor" href="#muc-đich" aria-label="Permalink to &quot;Mục đích&quot;">​</a></h2><p><code>task.md</code> trả lời câu hỏi <strong>&quot;Cần làm những bước cụ thể gì, xong bước nào chưa&quot;</strong> — chẻ <code>plan.md</code> thành checklist thực thi để dev tự theo dõi tiến độ và để người khác (Trung/reviewer) biết đang làm tới đâu mà không cần hỏi trực tiếp.</p><h2 id="ai-viet-khi-nao-viet" tabindex="-1">Ai viết, khi nào viết <a class="header-anchor" href="#ai-viet-khi-nao-viet" aria-label="Permalink to &quot;Ai viết, khi nào viết&quot;">​</a></h2><p>Dev tự viết ngay trước khi bắt đầu code, dựa trên <code>plan.md</code> đã có. Cập nhật (tick checkbox) liên tục trong lúc code — không viết 1 lần rồi bỏ quên, file này phải phản ánh đúng tiến độ thật tại mọi thời điểm.</p><h2 id="noi-dung-can-co" tabindex="-1">Nội dung cần có <a class="header-anchor" href="#noi-dung-can-co" aria-label="Permalink to &quot;Nội dung cần có&quot;">​</a></h2><ul><li>Checklist dạng <code>- [ ] việc cần làm</code> — mỗi dòng là một bước triển khai nhỏ, đủ cụ thể để biết &quot;làm xong&quot; nghĩa là gì (không viết mơ hồ kiểu &quot;làm backend&quot;, phải là &quot;viết <code>AgencyController.list()</code> + <code>AgencyService.findByOwnerId()</code>&quot;).</li><li>Thứ tự các bước theo đúng trình tự triển khai thật (thường: entity/schema → service logic → API endpoint → validate/error handling → frontend nếu có → viết test).</li><li>Đánh dấu rõ bước nào đang làm, bước nào chặn bởi task/FR khác (link tới FR đó).</li><li>Khi phát sinh việc ngoài dự kiến lúc code (bug, thiếu case) → thêm dòng mới vào đây, không giấu trong commit message.</li></ul><h2 id="ranh-gioi-voi-cac-file-khac" tabindex="-1">Ranh giới với các file khác <a class="header-anchor" href="#ranh-gioi-voi-cac-file-khac" aria-label="Permalink to &quot;Ranh giới với các file khác&quot;">​</a></h2><ul><li>Không lặp lại thiết kế kỹ thuật đã có trong <code>plan.md</code> — chỉ trỏ tới, mỗi dòng task chỉ là hành động ngắn.</li><li>Không phải nơi ghi log nghiệp vụ hay quyết định thiết kế — quyết định thiết kế mới phát sinh thì sửa <code>plan.md</code>, chỉ tick/thêm dòng hành động ở đây.</li><li>Khi tất cả checkbox đã tick và code đã qua <code>test.md</code> → FR coi như Done, không cần giữ file task ở trạng thái &quot;đang làm&quot; nữa.</li></ul>',9)])])}const k=t(c,[["render",h]]);export{m as __pageData,k as default};
